express-rate-limitパッケージを使います。

```bash
npm install express-rate-limit
```

```javascript
const rateLimit = require('express-rate-limit');

// 一般的なAPI制限
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15分
  max: 100, // 15分あたり100リクエスト
  message: 'リクエスト回数が上限に達しました'
});
app.use('/api/', apiLimiter);

// ログイン用の厳しい制限
const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // 15分あたり5回まで
  message: 'ログイン試行回数が上限に達しました'
});
app.use('/api/login', loginLimiter);
```

佐久間さんが指摘した「レート制限の欠如」はこれで解決できます。

CORS（Cross-Origin Resource Sharing）は「どのオリジンからのアクセスを許可するか」を制御します。

```bash
npm install cors
```

```javascript
const cors = require('cors');

// 悪い例: 全開放
app.use(cors()); // すべてのオリジンからアクセス可能

// 良い例: ホワイトリスト
const corsOptions = {
  origin: [
    'https://shimalink.com',
    'https://www.shimalink.com'
  ],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400 // preflight結果を24時間キャッシュ
};
app.use(cors(corsOptions));
```

開発環境ではlocalhostも追加します：
```javascript
if (process.env.NODE_ENV === 'development') {
  corsOptions.origin.push('http://localhost:3000');
}
```

CSRFトークンは、リクエストが正規のフォームから送信されたことを検証するランダムな文字列です。

**仕組み：**
```
1. サーバーがフォーム表示時にランダムなトークンを生成
2. フォームの隠しフィールドにトークンを埋め込み
3. フォーム送信時にトークンも一緒に送信
4. サーバーがトークンを検証 → 一致すれば正規のリクエスト
```

```javascript
// Express + csurf
const csrf = require('csurf');
const csrfProtection = csrf({ cookie: true });

app.get('/form', csrfProtection, (req, res) => {
  res.send(`<form action="/submit" method="POST">
    <input type="hidden" name="_csrf" value="${req.csrfToken()}">
    <button>送信</button>
  </form>`);
});

app.post('/submit', csrfProtection, (req, res) => {
  res.send('トークン検証OK');
});
```

IDOR（Insecure Direct Object Reference）は認可チェックで防ぎます。

```javascript
// 脆弱: IDだけでアクセス
app.get('/api/shops/:id', async (req, res) => {
  const shop = await prisma.shop.findUnique({
    where: { id: parseInt(req.params.id) }
  });
  res.json(shop);
});

// 安全: 所有者チェック付き
app.get('/api/shops/:id', authMiddleware, async (req, res) => {
  const shop = await prisma.shop.findFirst({
    where: {
      id: parseInt(req.params.id),
      ownerId: req.user.id  // ← 所有者チェック
    }
  });

  if (!shop) {
    return res.status(404).json({ error: '見つかりません' });
  }
  res.json(shop);
});
```

**ポイント**: 404を返す（403だと「データは存在するが権限がない」と情報漏洩になる）
